INSERT INTO `country_page_sections` VALUES (1,3,'hero','Study MBBS in Uzbekistan',0,'{\"image\": \"\", \"title\": \"Study MBBS in Uzbekistan\", \"subtitle\": \"Affordable Medical Education with Global Recognition\"}',1,'2026-06-20 17:14:56'),(2,3,'rich_text','Overview',1,'{\"content\": \"<p>Uzbekistan has become one of the fastest-growing destinations for Indian students pursuing MBBS abroad. With internationally recognized medical universities, affordable fee structures, quality education, and a student-friendly environment, Uzbekistan offers an excellent pathway to build a successful medical career.</p><h2>Why Choose Uzbekistan?</h2><p>Medical universities in Uzbekistan provide modern infrastructure, experienced faculty, practical clinical exposure, and internationally accepted medical degrees. The country is known for its affordable cost of education, comfortable living conditions, and increasing number of Indian students choosing MBBS programs every year.</p>\"}',1,'2026-06-20 17:14:56'),(3,3,'highlights','Key Highlights',2,'{\"items\": [\"NMC Recognized Universities\", \"WHO Recognized Degrees\", \"English Medium Programs\", \"Affordable Tuition Fees\", \"Indian Food Available\", \"Safe Student Environment\", \"Modern Medical Infrastructure\", \"Growing Indian Student Community\"]}',1,'2026-06-20 17:14:56'),(4,3,'table','MBBS Program Details',3,'{\"rows\": [[\"Degree\", \"MD (Equivalent to MBBS)\"], [\"Duration\", \"6 Years\"], [\"Medium\", \"English\"], [\"Eligibility\", \"NEET Qualified\"], [\"Recognition\", \"NMC & WHO\"], [\"Intake\", \"September / October\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 17:14:56'),(5,3,'table','Fee Structure',4,'{\"rows\": [[\"Tuition Fee\", \"₹2.9 – ₹3.4 Lakhs / Year\"], [\"Hostel\", \"₹50,000 / Year\"], [\"Food\", \"₹1,00,000 / Year\"], [\"One-Time Processing\", \"₹2,00,000 – ₹2,50,000\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 17:14:56'),(6,3,'rich_text','Fee Note',5,'{\"content\": \"<p><strong>Note:</strong> Fee structures may vary based on the university and prevailing exchange rates. Contact SVET for the latest admission and fee details specific to each university.</p>\"}',1,'2026-06-20 17:14:56'),(7,3,'universities','Featured Universities',6,'{\"universities\": [{\"name\": \"MIPER University, Tashkent\", \"description\": \"A modern medical university offering quality education, advanced facilities, and international exposure for medical students. The university has become a popular choice among Indian students due to its affordable fee structure and strong academic standards.\"}, {\"name\": \"Tashkent State Medical & Dental Institute\", \"description\": \"One of Uzbekistan\'s prominent medical institutions providing internationally recognized medical education with experienced faculty, clinical training, and modern infrastructure.\"}]}',1,'2026-06-20 17:14:56'),(8,3,'rich_text','Accommodation, Eligibility & Admission Process',7,'{\"content\": \"<h2>Accommodation &amp; Student Life</h2><p>Universities provide hostel facilities for international students with access to essential amenities. Indian food options are available in major student locations, helping students adapt comfortably to life abroad.</p><h2>Eligibility Criteria</h2><p>Applicants must have completed 10+2 with Physics, Chemistry, and Biology from a recognized board. NEET qualification is mandatory for Indian students seeking MBBS admission abroad as per current NMC guidelines.</p><h2>Admission Process</h2><ol><li>Submit Application</li><li>Document Verification</li><li>University Admission Letter</li><li>Visa Processing</li><li>Travel Preparation</li><li>University Enrollment</li></ol>\"}',1,'2026-06-20 17:14:56'),(9,3,'faq','Frequently Asked Questions',9,'{\"faqs\": [{\"answer\": \"Yes. NEET qualification is mandatory for Indian students seeking MBBS admission abroad as per NMC guidelines.\", \"question\": \"Is NEET mandatory for studying MBBS in Uzbekistan?\"}, {\"answer\": \"Yes. Universities listed by SVET offer internationally recognized medical degrees that are approved by NMC and WHO.\", \"question\": \"Is the MBBS degree from Uzbekistan recognized in India?\"}, {\"answer\": \"Yes. MBBS programs for international students in Uzbekistan are conducted entirely in English.\", \"question\": \"Is English the medium of instruction?\"}, {\"answer\": \"Yes. Hostel facilities are available for international students at most universities, with basic amenities provided.\", \"question\": \"Is hostel accommodation available for Indian students?\"}, {\"answer\": \"Yes. Indian restaurants and food options are available in major cities and near student campuses.\", \"question\": \"Is Indian food available in Uzbekistan?\"}]}',1,'2026-06-20 17:14:56'),(10,3,'cta',NULL,10,'{\"title\": \"Start Your Medical Journey in Uzbekistan\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 17:14:56'),(11,4,'hero','Study MBBS in Russia',0,'{\"image\": \"\", \"title\": \"Study MBBS in Russia\", \"subtitle\": \"Affordable Medical Education at Globally Recognized Universities\"}',1,'2026-06-20 17:28:27'),(12,4,'rich_text','Overview',1,'{\"content\": \"<p>Russia remains one of the most preferred destinations for Indian students pursuing MBBS abroad. Russian medical universities are known for affordable fee structures, experienced faculty, modern laboratories, and international recognition.</p><p>Students benefit from strong academic programs, practical training, comfortable hostel facilities, and a multicultural environment.</p>\"}',1,'2026-06-20 17:28:27'),(13,4,'highlights','Key Highlights',2,'{\"items\": [\"Affordable Tuition Fees\", \"Internationally Recognized Universities\", \"Modern Medical Infrastructure\", \"Clinical Exposure\", \"Hostel Facilities Available\", \"Indian Student Community\", \"Experienced Faculty\", \"6-Year Medical Program\"]}',1,'2026-06-20 17:28:27'),(14,4,'table','MBBS Program Details',3,'{\"rows\": [[\"Degree\", \"MD (Equivalent to MBBS)\"], [\"Duration\", \"6 Years\"], [\"Medium\", \"English\"], [\"Eligibility\", \"NEET Qualified\"], [\"Destination\", \"Russia\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 17:28:27'),(15,4,'table','Approximate Fee Structure',4,'{\"rows\": [[\"Tuition Fee\", \"Rs.2.2 - Rs.4.5 Lakhs / Year\"], [\"Hostel\", \"Included / University Specific\"], [\"Living Expenses\", \"$120 - $160 per Month\"], [\"One-Time Processing\", \"Rs.1.5 - Rs.2 Lakhs\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 17:28:27'),(16,4,'rich_text','Fee Note',5,'{\"content\": \"<p><strong>Note:</strong> Fees are approximate and may vary depending on the university and prevailing currency exchange rates.</p>\"}',1,'2026-06-20 17:28:27'),(17,4,'universities','Featured Universities',6,'{\"universities\": [{\"name\": \"Mordovia State University\", \"description\": \"One of Russia\'s established medical institutions offering modern medical education, research opportunities, and clinical training.\"}, {\"name\": \"Orel State University\", \"description\": \"Affordable MBBS destination for international students with strong academic support and practical learning opportunities.\"}, {\"name\": \"Crimea Federal University\", \"description\": \"Popular among international students for its quality medical education and student-friendly environment.\"}, {\"name\": \"Kemerovo State University\", \"description\": \"Provides comprehensive medical training with modern facilities and experienced faculty members.\"}]}',1,'2026-06-20 17:28:27'),(18,4,'rich_text','Accommodation, Eligibility & Admission Process',7,'{\"content\": \"<h2>Accommodation &amp; Student Life</h2><p>Russian universities provide hostel facilities for international students. Students benefit from a multicultural environment and access to essential amenities.</p><h2>Eligibility Criteria</h2><p>Students should complete 10+2 with Physics, Chemistry and Biology. NEET qualification is required for Indian students pursuing MBBS abroad.</p><h2>Admission Process</h2><ol><li>Submit Application</li><li>Document Verification</li><li>Admission Confirmation</li><li>Visa Processing</li><li>Travel Arrangements</li><li>University Enrollment</li></ol>\"}',1,'2026-06-20 17:28:27'),(19,4,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"The medical program duration is generally 6 years.\", \"question\": \"How long is MBBS in Russia?\"}, {\"answer\": \"Yes, NEET qualification is required for Indian students.\", \"question\": \"Is NEET required?\"}, {\"answer\": \"Yes, hostel accommodation is available at most universities.\", \"question\": \"Are hostel facilities available?\"}, {\"answer\": \"Russia offers some of the most affordable medical programs for international students.\", \"question\": \"Is Russia affordable for MBBS?\"}, {\"answer\": \"Yes, students receive practical clinical training as part of their medical education.\", \"question\": \"Do universities provide clinical exposure?\"}]}',1,'2026-06-20 17:28:27'),(20,4,'cta',NULL,9,'{\"title\": \"Start Your Medical Journey in Russia\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 17:28:27'),(21,5,'hero','Study Medicine in Philippines',0,'{\"image\": \"\", \"title\": \"Study Medicine in Philippines\", \"subtitle\": \"Quality Medical Education Through the Pre-Med & MD Pathway\"}',1,'2026-06-20 18:22:28'),(22,5,'rich_text','Overview',1,'{\"content\": \"<p>The Philippines has become a popular destination for students seeking medical education abroad. Medical colleges offer a structured pathway consisting of Pre-Medicine and Doctor of Medicine (MD) programs.</p><p>Students benefit from English-medium instruction, practical clinical training, and a learning environment that is familiar and comfortable for international students.</p>\"}',1,'2026-06-20 18:22:28'),(23,5,'highlights','Key Highlights',2,'{\"items\": [\"English Medium Education\", \"Pre-Med + MD Structure\", \"Clinical Training Opportunities\", \"International Student Environment\", \"Hostel Facilities Available\", \"Affordable Living Costs\", \"Experienced Faculty\", \"Recognized Medical Programs\"]}',1,'2026-06-20 18:22:28'),(24,5,'table','Program Details',3,'{\"rows\": [[\"Program\", \"Pre-Medicine + Doctor of Medicine (MD)\"], [\"Medium\", \"English\"], [\"Eligibility\", \"NEET Qualified\"], [\"Destination\", \"Philippines\"], [\"Clinical Exposure\", \"Included\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:22:28'),(25,5,'table','Approximate Fee Structure',4,'{\"rows\": [[\"Pre-Medicine Program\", \"University Specific\"], [\"MD Program\", \"₹3.8 – ₹5 Lakhs / Year\"], [\"Hostel & Food\", \"PHP 12,000 / Month\"], [\"Processing Fee\", \"₹50,000\"], [\"Visa & Documentation\", \"Additional\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:22:28'),(26,5,'rich_text','Fee Note',5,'{\"content\": \"<p><strong>Note:</strong> Fees may vary based on the selected college, exchange rates, accommodation type, and other university requirements.</p>\"}',1,'2026-06-20 18:22:28'),(27,5,'universities','Featured Medical Colleges',6,'{\"universities\": [{\"name\": \"PLTCI College of Medicine\", \"description\": \"Offers a structured medical education pathway with Pre-Medicine and MD programs, helping students build a strong foundation in medicine.\"}, {\"name\": \"Gullas College of Medicine\", \"description\": \"One of the well-known medical institutions in the Philippines, offering comprehensive medical training and clinical exposure.\"}]}',1,'2026-06-20 18:22:28'),(28,5,'rich_text','Accommodation, Eligibility & Admission Process',7,'{\"content\": \"<h2>Accommodation & Student Life</h2><p>Students can access hostel and accommodation facilities near the medical colleges. Food and daily living arrangements are available for international students throughout their study period.</p><h2>Eligibility Criteria</h2><p>Students must complete 10+2 with Physics, Chemistry and Biology. NEET qualification is required for Indian students seeking admission abroad.</p><h2>Admission Process</h2><ol><li>Application Submission</li><li>Document Verification</li><li>Admission Confirmation</li><li>Visa Processing</li><li>Travel Arrangements</li><li>College Enrollment</li></ol>\"}',1,'2026-06-20 18:22:28'),(29,5,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"Students generally complete a Pre-Medicine program followed by the Doctor of Medicine (MD) program.\", \"question\": \"What is the study structure in the Philippines?\"}, {\"answer\": \"Yes, NEET qualification is required for Indian students pursuing medical education abroad.\", \"question\": \"Is NEET required for Indian students?\"}, {\"answer\": \"Yes, medical programs are conducted in English.\", \"question\": \"Is English the medium of instruction?\"}, {\"answer\": \"Yes, accommodation and hostel facilities are available for international students.\", \"question\": \"Are hostel facilities available?\"}, {\"answer\": \"Yes, students can access food and accommodation arrangements throughout their studies.\", \"question\": \"Are food and living facilities available?\"}]}',1,'2026-06-20 18:22:28'),(30,5,'cta',NULL,9,'{\"title\": \"Start Your Medical Journey in Philippines\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:22:28'),(31,6,'hero','Study MBBS in Georgia',0,'{\"image\": \"\", \"title\": \"Study MBBS in Georgia\", \"subtitle\": \"Quality Medical Education in a Modern European Environment\"}',1,'2026-06-20 18:26:58'),(32,6,'rich_text','Overview',1,'{\"content\": \"<p>Georgia has emerged as one of the leading destinations for students seeking medical education abroad. With modern infrastructure, experienced faculty, and internationally recognized universities, Georgia attracts students from around the world.</p><p>The country offers quality medical education, comfortable living conditions, and an environment that supports academic excellence and professional development.</p>\"}',1,'2026-06-20 18:26:58'),(33,6,'highlights','Key Highlights',2,'{\"items\": [\"Modern Medical Universities\", \"International Student Environment\", \"Advanced Clinical Training\", \"English Medium Programs\", \"European Lifestyle\", \"Comfortable Accommodation\", \"Experienced Faculty\", \"6-Year Medical Program\"]}',1,'2026-06-20 18:26:58'),(34,6,'table','MBBS Program Details',3,'{\"rows\": [[\"Degree\", \"MD (Equivalent to MBBS)\"], [\"Duration\", \"6 Years\"], [\"Medium\", \"English\"], [\"Eligibility\", \"NEET Qualified\"], [\"Destination\", \"Georgia\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:26:58'),(35,6,'table','Approximate Fee Structure',4,'{\"rows\": [[\"Tuition Fee\", \"₹4.15 – ₹7.5 Lakhs / Year\"], [\"Accommodation\", \"University Specific\"], [\"Living Expenses\", \"As Per University Guidelines\"], [\"One-Time Processing\", \"₹2 – ₹2.5 Lakhs\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:26:58'),(36,6,'rich_text','Fee Note',5,'{\"content\": \"<p><strong>Note:</strong> Fee structures may vary depending on the selected university and prevailing exchange rates. Contact SVET for updated admission and fee information.</p>\"}',1,'2026-06-20 18:26:58'),(37,6,'universities','Featured Universities',6,'{\"universities\": [{\"name\": \"Batumi Shota Rustaveli State University\", \"description\": \"A well-known public university offering medical education with modern facilities, academic excellence, and clinical exposure.\"}, {\"name\": \"Tbilisi State Medical University\", \"description\": \"One of the most recognized medical universities in Georgia, providing quality education, advanced training, and international recognition.\"}]}',1,'2026-06-20 18:26:58'),(38,6,'rich_text','Accommodation, Eligibility & Admission Process',7,'{\"content\": \"<h2>Accommodation & Student Life</h2><p>Universities in Georgia provide accommodation facilities for international students. Students enjoy a safe environment, modern amenities, and opportunities to interact with peers from different countries.</p><h2>Eligibility Criteria</h2><p>Applicants should complete 10+2 with Physics, Chemistry and Biology from a recognized board. NEET qualification is required for Indian students.</p><h2>Admission Process</h2><ol><li>Application Submission</li><li>Document Verification</li><li>Admission Confirmation</li><li>Visa Processing</li><li>Travel Arrangements</li><li>University Registration</li></ol>\"}',1,'2026-06-20 18:26:58'),(39,6,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"The medical program generally has a duration of 6 years.\", \"question\": \"How long is the MBBS program in Georgia?\"}, {\"answer\": \"Yes, Indian students are required to qualify NEET.\", \"question\": \"Is NEET required for admission?\"}, {\"answer\": \"Yes, accommodation facilities are available for international students.\", \"question\": \"Are hostel facilities available?\"}, {\"answer\": \"Students prefer Georgia because of its quality education, modern infrastructure, and international learning environment.\", \"question\": \"Why do students choose Georgia for MBBS?\"}, {\"answer\": \"Yes, universities provide clinical exposure and practical training throughout the program.\", \"question\": \"Do universities provide practical medical training?\"}]}',1,'2026-06-20 18:26:58'),(40,6,'cta',NULL,9,'{\"title\": \"Start Your Medical Journey in Georgia\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:26:58'),(41,7,'hero','Study Medicine in Malaysia',0,'{\"image\": \"\", \"title\": \"Study Medicine in Malaysia\", \"subtitle\": \"International Medical Education with Global Opportunities\"}',1,'2026-06-20 18:30:42'),(42,7,'rich_text','Overview',1,'{\"content\": \"<p>Malaysia has become a preferred destination for international students seeking medical education in a modern and multicultural environment. The country offers globally focused medical programs with advanced learning facilities and international exposure.</p><p>Students benefit from English-medium instruction, comfortable living conditions, and opportunities to pursue internationally recognized medical pathways.</p>\"}',1,'2026-06-20 18:30:42'),(43,7,'highlights','Key Highlights',2,'{\"items\": [\"English Medium Education\", \"Modern Medical Infrastructure\", \"International Learning Environment\", \"Indian Food Available\", \"USMLE Preparation Support\", \"PLAB Preparation Support\", \"Multicultural Student Community\", \"Global Career Opportunities\"]}',1,'2026-06-20 18:30:42'),(44,7,'table','Program Details',3,'{\"rows\": [[\"Program\", \"Medicine\"], [\"Medium\", \"English\"], [\"Country\", \"Malaysia\"], [\"Food\", \"Indian Food Available\"], [\"Career Pathway\", \"USMLE & PLAB Focus\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:30:42'),(45,7,'table','Approximate Fee Structure',4,'{\"rows\": [[\"Program Package\", \"₹60 Lakhs\"], [\"Accommodation\", \"University Specific\"], [\"Food\", \"Additional\"], [\"Visa & Documentation\", \"Additional\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:30:42'),(46,7,'rich_text','Fee Note',5,'{\"content\": \"<p><strong>Note:</strong> Fee structures may vary based on university requirements, accommodation preferences, and prevailing exchange rates.</p>\"}',1,'2026-06-20 18:30:42'),(47,7,'universities','Study Opportunities',6,'{\"universities\": [{\"name\": \"Medical Universities in Malaysia\", \"description\": \"Malaysia offers internationally focused medical education through universities equipped with modern facilities and global academic standards.\"}]}',1,'2026-06-20 18:30:42'),(48,7,'rich_text','Student Life, Eligibility & Admission Process',7,'{\"content\": \"<h2>Student Life</h2><p>Malaysia provides a safe and multicultural environment with modern infrastructure, international communities, and convenient access to food and accommodation options.</p><h2>Eligibility Criteria</h2><p>Students should complete their qualifying education as per admission requirements and fulfill eligibility criteria applicable for international admissions.</p><h2>Admission Process</h2><ol><li>Application Submission</li><li>Document Verification</li><li>University Admission Approval</li><li>Visa Processing</li><li>Travel Arrangements</li><li>University Enrollment</li></ol>\"}',1,'2026-06-20 18:30:42'),(49,7,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"Malaysia offers modern infrastructure, English-medium education, and international exposure.\", \"question\": \"Why choose Malaysia for medical education?\"}, {\"answer\": \"Yes, medical programs are generally offered in English.\", \"question\": \"Is English used for teaching?\"}, {\"answer\": \"Yes, Indian food options are available in Malaysia.\", \"question\": \"Is Indian food available?\"}, {\"answer\": \"The brochure highlights USMLE and PLAB-focused opportunities.\", \"question\": \"Does the program support international licensing pathways?\"}, {\"answer\": \"Accommodation options are available depending on the university.\", \"question\": \"Are accommodation facilities available?\"}]}',1,'2026-06-20 18:30:42'),(50,7,'cta',NULL,9,'{\"title\": \"Start Your Medical Journey in Malaysia\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:30:42'),(51,8,'hero','Study in Germany',0,'{\"image\": \"\", \"title\": \"Study in Germany\", \"subtitle\": \"World-Class Education and Research Opportunities\"}',1,'2026-06-20 18:37:16'),(52,8,'rich_text','Overview',1,'{\"content\": \"<p>Germany is one of the most respected destinations for higher education worldwide. Known for academic excellence, advanced research facilities, and strong industry connections, Germany attracts students from across the globe.</p><p>Students benefit from modern infrastructure, practical learning methods, and opportunities to build successful international careers.</p>\"}',1,'2026-06-20 18:37:16'),(53,8,'highlights','Key Highlights',2,'{\"items\": [\"Globally Recognized Universities\", \"Research-Oriented Education\", \"Advanced Healthcare Infrastructure\", \"Modern Learning Environment\", \"International Student Community\", \"Practical Industry Exposure\", \"Strong Career Opportunities\", \"High Academic Standards\"]}',1,'2026-06-20 18:37:16'),(54,8,'table','Program Details',3,'{\"rows\": [[\"Country\", \"Germany\"], [\"Education System\", \"International Standard\"], [\"Learning Style\", \"Research & Practical Based\"], [\"Student Community\", \"Global\"], [\"Career Scope\", \"Excellent\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:37:16'),(55,8,'table','Approximate Cost Information',4,'{\"rows\": [[\"Starting Package\", \"₹12 Lakhs\"], [\"Accommodation\", \"University Specific\"], [\"Living Expenses\", \"Additional\"], [\"Visa & Documentation\", \"Additional\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:37:16'),(56,8,'rich_text','Why Choose Germany?',5,'{\"content\": \"<p>Germany is renowned for its innovation, technology, and academic excellence. Students gain access to world-class facilities, experienced faculty, and research opportunities that prepare them for successful careers.</p><p>The country\'s strong economy and international environment make it a preferred destination for students seeking global exposure and professional growth.</p>\"}',1,'2026-06-20 18:37:16'),(57,8,'universities','Study Opportunities',6,'{\"universities\": [{\"name\": \"Universities in Germany\", \"description\": \"Germany offers globally recognized higher education institutions known for academic excellence, research innovation, and international recognition.\"}]}',1,'2026-06-20 18:37:16'),(58,8,'rich_text','Student Life, Eligibility & Admission Process',7,'{\"content\": \"<h2>Student Life</h2><p>Germany offers a multicultural environment with excellent infrastructure, modern transportation, and a high standard of living for international students.</p><h2>Eligibility Criteria</h2><p>Eligibility requirements vary depending on the selected university and academic program.</p><h2>Admission Process</h2><ol><li>Application Submission</li><li>Document Verification</li><li>University Evaluation</li><li>Admission Confirmation</li><li>Visa Processing</li><li>Travel & Enrollment</li></ol>\"}',1,'2026-06-20 18:37:16'),(59,8,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"Germany is known for academic excellence, research opportunities, and globally recognized qualifications.\", \"question\": \"Why study in Germany?\"}, {\"answer\": \"Yes, Germany hosts a large international student community from around the world.\", \"question\": \"Are international students welcome in Germany?\"}, {\"answer\": \"Modern infrastructure, strong academic standards, and career opportunities make Germany a preferred destination.\", \"question\": \"What makes Germany attractive for higher education?\"}, {\"answer\": \"Accommodation options are available depending on the university and location.\", \"question\": \"Are accommodation facilities available?\"}, {\"answer\": \"Germany offers excellent opportunities for professional development and international career growth.\", \"question\": \"Can students build international careers after graduation?\"}]}',1,'2026-06-20 18:37:16'),(60,8,'cta',NULL,9,'{\"title\": \"Start Your Study Journey in Germany\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:37:16'),(61,9,'hero','Study in Singapore',0,'{\"image\": \"\", \"title\": \"Study in Singapore\", \"subtitle\": \"Global Education Hub with World-Class Academic Excellence\"}',1,'2026-06-20 18:39:16'),(62,9,'rich_text','Overview',1,'{\"content\": \"<p>Singapore has established itself as one of Asia\'s leading education destinations, offering internationally recognized qualifications, modern infrastructure, and a strong focus on innovation and technology.</p><p>Students benefit from a safe environment, multicultural society, excellent academic standards, and access to global career opportunities.</p>\"}',1,'2026-06-20 18:39:16'),(63,9,'highlights','Key Highlights',2,'{\"items\": [\"World-Class Education System\", \"Globally Recognized Qualifications\", \"English Medium Instruction\", \"Modern Healthcare Infrastructure\", \"Safe & Student-Friendly Environment\", \"Innovation & Technology Focus\", \"International Student Community\", \"Excellent Career Opportunities\"]}',1,'2026-06-20 18:39:16'),(64,9,'table','Program Details',3,'{\"rows\": [[\"Country\", \"Singapore\"], [\"Medium of Instruction\", \"English\"], [\"Education Standard\", \"International\"], [\"Student Environment\", \"Multicultural\"], [\"Career Opportunities\", \"Global\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:39:16'),(65,9,'table','Approximate Cost Information',4,'{\"rows\": [[\"Starting Package\", \"₹15 Lakhs\"], [\"Accommodation\", \"University Specific\"], [\"Living Expenses\", \"Additional\"], [\"Visa & Documentation\", \"Additional\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:39:16'),(66,9,'rich_text','Why Choose Singapore?',5,'{\"content\": \"<p>Singapore combines academic excellence with modern infrastructure, making it one of the most attractive study destinations in Asia. The country is known for its quality education system, innovation-driven economy, and strong global connectivity.</p><p>Students gain valuable international exposure while studying in a safe, clean, and technologically advanced environment.</p>\"}',1,'2026-06-20 18:39:16'),(67,9,'universities','Study Opportunities',6,'{\"universities\": [{\"name\": \"Institutions in Singapore\", \"description\": \"Singapore offers internationally respected institutions known for academic excellence, research innovation, and industry-focused learning.\"}]}',1,'2026-06-20 18:39:16'),(68,9,'rich_text','Student Life, Eligibility & Admission Process',7,'{\"content\": \"<h2>Student Life</h2><p>Singapore provides a modern and vibrant lifestyle with excellent public transportation, multicultural communities, and world-class facilities.</p><h2>Eligibility Criteria</h2><p>Admission requirements vary depending on the selected institution and academic program.</p><h2>Admission Process</h2><ol><li>Application Submission</li><li>Document Verification</li><li>Institution Evaluation</li><li>Admission Confirmation</li><li>Visa Processing</li><li>Travel & Enrollment</li></ol>\"}',1,'2026-06-20 18:39:16'),(69,9,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"Singapore offers globally recognized education, modern infrastructure, and excellent career opportunities.\", \"question\": \"Why choose Singapore for higher education?\"}, {\"answer\": \"Yes, English is widely used as the medium of instruction in Singapore.\", \"question\": \"Is English the medium of instruction?\"}, {\"answer\": \"Singapore is considered one of the safest countries for students.\", \"question\": \"Is Singapore safe for international students?\"}, {\"answer\": \"Yes, accommodation options are available depending on the institution.\", \"question\": \"Are accommodation facilities available?\"}, {\"answer\": \"Singapore offers strong career opportunities due to its global business environment and growing industries.\", \"question\": \"What career opportunities are available after graduation?\"}]}',1,'2026-06-20 18:39:16'),(70,9,'cta',NULL,9,'{\"title\": \"Start Your Study Journey in Singapore\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:39:16'),(71,10,'hero','Study in the United States',0,'{\"image\": \"\", \"title\": \"Study in the United States\", \"subtitle\": \"World-Leading Education, Innovation & Research Opportunities\"}',1,'2026-06-20 18:41:40'),(72,10,'rich_text','Overview',1,'{\"content\": \"<p>The United States is one of the most popular destinations for international students, offering world-class universities, cutting-edge research facilities, and globally recognized qualifications.</p><p>Students benefit from innovation-driven learning, diverse academic programs, and opportunities to build successful international careers across various industries.</p>\"}',1,'2026-06-20 18:41:40'),(73,10,'highlights','Key Highlights',2,'{\"items\": [\"World-Leading Universities\", \"Advanced Research Opportunities\", \"Innovation-Focused Education\", \"Global Career Pathways\", \"Modern Learning Environment\", \"International Student Community\", \"Industry-Oriented Programs\", \"Strong Professional Network\"]}',1,'2026-06-20 18:41:40'),(74,10,'table','Program Details',3,'{\"rows\": [[\"Country\", \"United States\"], [\"Education Standard\", \"Global\"], [\"Medium of Instruction\", \"English\"], [\"Learning Style\", \"Research & Practical Based\"], [\"Career Scope\", \"Excellent\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:41:40'),(75,10,'table','Approximate Cost Information',4,'{\"rows\": [[\"Starting Package\", \"₹25 Lakhs\"], [\"Accommodation\", \"University Specific\"], [\"Living Expenses\", \"Additional\"], [\"Visa & Documentation\", \"Additional\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:41:40'),(76,10,'rich_text','Why Choose the USA?',5,'{\"content\": \"<p>The United States is recognized globally for academic excellence, innovation, and leadership in education. Students gain access to world-renowned faculty, advanced facilities, and research-driven learning.</p><p>Studying in the USA provides international exposure, networking opportunities, and access to some of the world\'s most respected organizations and industries.</p>\"}',1,'2026-06-20 18:41:40'),(77,10,'universities','Study Opportunities',6,'{\"universities\": [{\"name\": \"Universities in the United States\", \"description\": \"The United States offers globally recognized institutions known for academic excellence, innovation, research leadership, and strong industry partnerships.\"}]}',1,'2026-06-20 18:41:40'),(78,10,'rich_text','Student Life, Eligibility & Admission Process',7,'{\"content\": \"<h2>Student Life</h2><p>The USA provides a vibrant multicultural environment where students can participate in academic, cultural, and professional activities while building a global network.</p><h2>Eligibility Criteria</h2><p>Admission requirements vary depending on the selected university and program. Students may be required to submit academic records and supporting documents.</p><h2>Admission Process</h2><ol><li>Choose Your Program</li><li>Submit Application</li><li>Document Verification</li><li>Admission Evaluation</li><li>Offer Letter Issuance</li><li>Visa Processing</li><li>Travel & Enrollment</li></ol>\"}',1,'2026-06-20 18:41:40'),(79,10,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"The USA offers globally recognized universities, advanced research opportunities, and excellent career prospects.\", \"question\": \"Why study in the USA?\"}, {\"answer\": \"Yes, English is the primary language of instruction in American universities.\", \"question\": \"Is English the medium of instruction?\"}, {\"answer\": \"Yes, the USA hosts one of the largest international student communities in the world.\", \"question\": \"Are international students welcomed in the USA?\"}, {\"answer\": \"Graduates benefit from global recognition and opportunities across various industries worldwide.\", \"question\": \"What are the career opportunities after graduation?\"}, {\"answer\": \"Universities provide various accommodation options including campus housing and private residences.\", \"question\": \"Are accommodation facilities available?\"}]}',1,'2026-06-20 18:41:40'),(80,10,'cta',NULL,9,'{\"title\": \"Start Your Study Journey in the USA\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:41:40'),(81,11,'hero','Study MBBS in Kyrgyzstan',0,'{\"image\": \"\", \"title\": \"Study MBBS in Kyrgyzstan\", \"subtitle\": \"Affordable Medical Education with International Exposure\"}',1,'2026-06-20 18:43:54'),(82,11,'rich_text','Overview',1,'{\"content\": \"<p>Kyrgyzstan has become one of the preferred destinations for students seeking affordable medical education abroad. The country offers English-medium MBBS programs, modern teaching facilities, and a growing international student community.</p><p>Medical universities in Kyrgyzstan provide quality education, practical clinical exposure, and a student-friendly environment at comparatively affordable costs.</p>\"}',1,'2026-06-20 18:43:54'),(83,11,'highlights','Key Highlights',2,'{\"items\": [\"Affordable Tuition Fees\", \"English Medium Programs\", \"Recognized Medical Education\", \"Hostel Facilities Available\", \"International Student Community\", \"Clinical Exposure & Practical Training\", \"Student-Friendly Environment\", \"Growing Popularity Among Indian Students\"]}',1,'2026-06-20 18:43:54'),(84,11,'table','MBBS Program Details',3,'{\"rows\": [[\"Degree\", \"MBBS / MD Equivalent\"], [\"Duration\", \"5–6 Years\"], [\"Medium\", \"English\"], [\"Eligibility\", \"NEET Qualified\"], [\"Country\", \"Kyrgyzstan\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:43:54'),(85,11,'table','Approximate Fee Structure',4,'{\"rows\": [[\"Starting Tuition Fee\", \"₹3 Lakhs / Year\"], [\"Hostel\", \"University Specific\"], [\"Food & Living Expenses\", \"Additional\"], [\"Visa & Documentation\", \"Additional\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:43:54'),(86,11,'rich_text','Why Choose Kyrgyzstan?',5,'{\"content\": \"<p>Kyrgyzstan is an attractive destination for students looking for cost-effective medical education without compromising on academic quality. Universities provide experienced faculty, practical learning opportunities, and a supportive environment for international students.</p><p>The affordable cost of living and growing Indian student population make Kyrgyzstan a popular choice for MBBS aspirants.</p>\"}',1,'2026-06-20 18:43:54'),(87,11,'universities','Study Opportunities',6,'{\"universities\": [{\"name\": \"Medical Universities in Kyrgyzstan\", \"description\": \"Kyrgyzstan offers affordable medical education through universities focused on practical training, international exposure, and student support services.\"}]}',1,'2026-06-20 18:43:54'),(88,11,'rich_text','Student Life, Eligibility & Admission Process',7,'{\"content\": \"<h2>Student Life</h2><p>Students enjoy a comfortable and affordable lifestyle with access to hostel facilities, essential amenities, and multicultural communities.</p><h2>Eligibility Criteria</h2><p>Students should complete 10+2 with Physics, Chemistry, and Biology. NEET qualification is required for Indian students seeking MBBS admission abroad.</p><h2>Admission Process</h2><ol><li>Submit Application</li><li>Document Verification</li><li>Admission Confirmation</li><li>Visa Processing</li><li>Travel Arrangements</li><li>University Enrollment</li></ol>\"}',1,'2026-06-20 18:43:54'),(89,11,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"Kyrgyzstan offers affordable medical education, English-medium programs, and a growing international student community.\", \"question\": \"Why study MBBS in Kyrgyzstan?\"}, {\"answer\": \"Yes, NEET qualification is required for Indian students pursuing MBBS abroad.\", \"question\": \"Is NEET required for Indian students?\"}, {\"answer\": \"Yes, universities provide hostel and accommodation facilities for international students.\", \"question\": \"Are hostel facilities available?\"}, {\"answer\": \"Yes, many medical universities offer English-medium MBBS programs.\", \"question\": \"Is English the medium of instruction?\"}, {\"answer\": \"Yes, Kyrgyzstan is considered one of the most affordable destinations for medical education abroad.\", \"question\": \"Is Kyrgyzstan affordable for students?\"}]}',1,'2026-06-20 18:43:54'),(90,11,'cta',NULL,9,'{\"title\": \"Start Your MBBS Journey in Kyrgyzstan\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:43:54'),(91,12,'hero','Study in the United Kingdom',0,'{\"image\": \"\", \"title\": \"Study in the United Kingdom\", \"subtitle\": \"World-Class Education with Global Career Opportunities\"}',1,'2026-06-20 18:46:09'),(92,12,'rich_text','Overview',1,'{\"content\": \"<p>The United Kingdom is one of the world\'s most respected destinations for higher education, attracting students from across the globe. Universities in the UK are known for academic excellence, research opportunities, and internationally recognized qualifications.</p><p>Students benefit from modern campuses, multicultural environments, and strong career pathways after graduation.</p>\"}',1,'2026-06-20 18:46:09'),(93,12,'highlights','Key Highlights',2,'{\"items\": [\"World-Class Universities\", \"Scholarships Available\", \"Offer Letter Within 48 Hours\", \"Part-Time Work Opportunities\", \"Internationally Recognized Degrees\", \"Multicultural Student Environment\", \"Excellent Career Prospects\", \"Global Learning Experience\"]}',1,'2026-06-20 18:46:09'),(94,12,'table','Program Details',3,'{\"rows\": [[\"Country\", \"United Kingdom\"], [\"Admission Status\", \"Open\"], [\"Scholarship\", \"Up To £6000\"], [\"Offer Letter\", \"Within 48 Hours\"], [\"Part-Time Jobs\", \"Available\"]], \"columns\": [\"Particular\", \"Details\"]}',1,'2026-06-20 18:46:09'),(95,12,'table','Approximate Cost Information',4,'{\"rows\": [[\"Starting Package\", \"₹9 Lakhs\"], [\"Scholarship\", \"Up To £6000\"], [\"Accommodation\", \"University Specific\"], [\"Visa & Documentation\", \"Additional\"]], \"columns\": [\"Particular\", \"Approximate Cost\"]}',1,'2026-06-20 18:46:09'),(96,12,'rich_text','Scholarship & Career Opportunities',5,'{\"content\": \"<p>Students may be eligible for scholarships of up to £6000, depending on the university and academic profile.</p><p>The UK also provides opportunities for part-time employment, allowing students to gain work experience while pursuing their studies.</p>\"}',1,'2026-06-20 18:46:09'),(97,12,'universities','Study Opportunities',6,'{\"universities\": [{\"name\": \"Universities in the United Kingdom\", \"description\": \"The brochure highlights study opportunities across the UK with fast admission processing, scholarship opportunities, and global recognition.\"}]}',1,'2026-06-20 18:46:09'),(98,12,'rich_text','Student Life, Eligibility & Admission Process',7,'{\"content\": \"<h2>Student Life</h2><p>The United Kingdom offers a vibrant multicultural environment, modern facilities, and opportunities to engage with students from around the world.</p><h2>Eligibility Criteria</h2><p>Eligibility requirements vary depending on the selected university and academic program.</p><h2>Admission Process</h2><ol><li>Application Submission</li><li>Document Verification</li><li>University Evaluation</li><li>Offer Letter Issuance</li><li>Visa Processing</li><li>Travel & Enrollment</li></ol>\"}',1,'2026-06-20 18:46:09'),(99,12,'faq','Frequently Asked Questions',8,'{\"faqs\": [{\"answer\": \"The brochure states that offer letters can be issued within 48 hours.\", \"question\": \"How quickly can I receive an offer letter?\"}, {\"answer\": \"Yes, scholarships up to £6000 are highlighted in the brochure.\", \"question\": \"Are scholarships available?\"}, {\"answer\": \"Yes, part-time work opportunities are available.\", \"question\": \"Can students work while studying?\"}, {\"answer\": \"The UK offers globally recognized qualifications, excellent academic standards, and strong career opportunities.\", \"question\": \"Why choose the UK for higher education?\"}, {\"answer\": \"Accommodation facilities vary by university and program.\", \"question\": \"Are accommodation options available?\"}]}',1,'2026-06-20 18:46:09'),(100,12,'cta',NULL,9,'{\"title\": \"Start Your Study Journey in the United Kingdom\", \"buttonText\": \"Apply Now\"}',1,'2026-06-20 18:46:09'),(101,3,'gallery','IMAGE GALLERY',8,'{\"images\": [\"/uploads/countries/gallery/ad474277cf.jpeg\"]}',1,'2026-06-20 18:57:53');
