INSERT INTO `country_seo` VALUES (1,3,'Study MBBS in Uzbekistan | SVET Overseas Medical Admissions','Study MBBS in Uzbekistan at NMC and WHO recognized universities. Affordable fee starting from ₹2.9 Lakhs/year, English medium, Indian food available. Apply through SVET for complete admission guidance.','MBBS Uzbekistan, study medicine Uzbekistan, NMC approved Uzbekistan, MIPER University, Tashkent Medical, MBBS abroad India, affordable MBBS, SVET overseas, MBBS 2025 Uzbekistan',''),(2,4,'Study MBBS in Russia | SVET Overseas Medical Admissions','Study MBBS in Russia at leading medical universities. Affordable fees, modern infrastructure, hostel facilities, and international recognition.','MBBS Russia, Study Medicine Russia, Orel State University, Crimea Federal University, Kemerovo State University, Mordovia State University, MBBS Abroad Russia, SVET',''),(3,5,'Study Medicine in Philippines | SVET Overseas Medical Admissions','Study Medicine in the Philippines through leading medical colleges. English-medium education, Pre-Med and MD programs, hostel facilities, and complete admission guidance from SVET.','Medicine Philippines, MBBS Philippines, Doctor of Medicine Philippines, PLTCI College of Medicine, Gullas College of Medicine, Medical Education Philippines, Study Medicine Abroad, SVET',''),(4,6,'Study MBBS in Georgia | SVET Overseas Medical Admissions','Study MBBS in Georgia at reputed medical universities. Quality education, international exposure, modern infrastructure, and expert admission guidance.','MBBS Georgia, Study Medicine Georgia, Tbilisi State Medical University, Batumi Shota Rustaveli State University, Medical Education Georgia, MBBS Abroad Georgia, SVET Overseas',''),(5,7,'Study Medicine in Malaysia | SVET Overseas Medical Admissions','Study Medicine in Malaysia with English-medium education, modern facilities, international exposure, and guidance from SVET Overseas.','Medicine Malaysia, MBBS Malaysia, Study Medicine Malaysia, Medical Education Malaysia, USMLE Malaysia, PLAB Malaysia, SVET Overseas Malaysia',''),(6,8,'Study in Germany | SVET Overseas Medical Admissions','Study in Germany at world-class universities. Research-oriented education, practical industry exposure, and complete admission guidance from SVET.','Study in Germany, Universities in Germany, Higher Education Germany, Germany Study Opportunities, SVET Overseas',''),(7,9,'Study in Singapore | SVET Overseas Medical Admissions','Study in Singapore at top universities. Global education hub, world-class academic excellence, safe environment, and complete admission guidance from SVET.','Study in Singapore, Universities in Singapore, Higher Education Singapore, Singapore Study Opportunities, SVET Overseas',''),(8,10,'Study in USA | SVET Overseas Admissions','Study in the USA with globally recognized universities, advanced research, modern facilities, and strong career opportunities.','Study USA, USA Universities, Higher Education USA, Study Abroad USA, Medical Education USA, SVET',''),(9,11,'Study MBBS in Kyrgyzstan | SVET Overseas Admissions','Study MBBS in Kyrgyzstan with affordable tuition fees, English-medium programs, hostel facilities, and international student support.','MBBS Kyrgyzstan, Study Medicine Kyrgyzstan, Medical Universities Kyrgyzstan, Affordable MBBS Abroad, SVET',''),(10,12,'Study in the United Kingdom | SVET Overseas Admissions','Study in the United Kingdom with scholarship opportunities, fast admission processing, globally recognized degrees, and expert guidance from SVET.','Study UK, United Kingdom Education, UK Universities, Study Abroad UK, Scholarship UK, UK Admissions, SVET Overseas UK','');
